package com.travelmate.model;

import java.util.ArrayList;
import java.util.List;

/**
 * Deterministic travel suitability advice and recommendations generated by the weather heuristics engine.
 */
public class WeatherAdvice {
    public boolean success = true;
    public String targetDate;
    public Double latitude;
    public Double longitude;
    public String primaryCondition;
    public int impactScore; // 0..100 (100 = optimal outdoor conditions)
    public String impactRating; // "Optimal", "Good", "Challenging", "Severe"
    public boolean severeWarning;
    public List<ActivitySuitability> activities = new ArrayList<>();
    public List<RecommendationItem> recommendations = new ArrayList<>();
    public DailyForecast forecast;
}

